    {
      "category": "open_connection",
      "components": ["U4", "C7"],
      "pins": ["U4.28", "C7.1"],
      "nets": ["Net-(U4-VCC)", "VCC"],
      "observed": "U4 pin 28 (VCC) is connected only to C7 pin 1 on Net-(U4-VCC); C7 pin 2 is GND. The global VCC net contains U4 pins 6 (VBAT), 9 (VDD), and 11 (BS1), but does not contain U4 pin 28.",
      "expected": "U4 pin 28 is named VCC and is typed power_in in the SSD1306 libpart. A supply pin of this type should be connected to a DC supply rail, with C7 serving as its bypass capacitor, rather than left on an isolated net with only a capacitor to ground.",
      "evidence": [
        {"source": "netlist", "quote": "(net (code \"17\") (name \"Net-(U4-VCC)\") (node (ref \"C7\") (pin \"1\") (pintype \"passive\")) (node (ref \"U4\") (pin \"28\") (pinfunction \"VCC\") (pintype \"power_in\")))"},
        {"source": "netlist", "quote": "(pin (num \"28\") (name \"VCC\") (type \"power_in\"))"},
        {"source": "spec", "quote": "C7 (2.2 µF) — U4 VCC (digital-logic supply pin) to GND"}
      ],
      "impact": "The SSD1306 display-driver supply pin would be unpowered; the OLED may fail to initialize or display even though U4 VDD and VBAT are connected to the main VCC rail.",
      "confidence": 0.6
    }
  ],
  "summary": "Most connectivity matches the specification, but U4 pin 28 VCC appears to be an isolated bypass net rather than a connected supply pin, which is a plausible board-level anomaly."
}

